BEGIN;
CREATE TABLE IF NOT EXISTS protocol.pool_snapshots(id bigserial PRIMARY KEY,pool_address text NOT NULL REFERENCES protocol.pools(address),chain_slot bigint,active_bin_id integer NOT NULL,base_fee_pct numeric,dynamic_fee_pct numeric,max_fee_pct numeric,protocol_fee_pct numeric,reserve_x numeric(78,0),reserve_y numeric(78,0),observed_at timestamptz NOT NULL,source text NOT NULL,raw jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS pool_snapshots_pool_time_idx ON protocol.pool_snapshots(pool_address,observed_at DESC);
CREATE TABLE IF NOT EXISTS protocol.bin_snapshots(pool_address text NOT NULL REFERENCES protocol.pools(address),bin_id integer NOT NULL,chain_slot bigint,price numeric,amount_x numeric(78,0) NOT NULL DEFAULT 0,amount_y numeric(78,0) NOT NULL DEFAULT 0,liquidity_supply numeric(78,0),observed_at timestamptz NOT NULL,source text NOT NULL,PRIMARY KEY(pool_address,bin_id,observed_at));
CREATE INDEX IF NOT EXISTS bin_snapshots_pool_time_idx ON protocol.bin_snapshots(pool_address,observed_at DESC,bin_id);
CREATE TABLE IF NOT EXISTS protocol.positions(address text PRIMARY KEY,pool_address text NOT NULL REFERENCES protocol.pools(address),owner text NOT NULL,fee_owner text,lower_bin_id integer NOT NULL,upper_bin_id integer NOT NULL,last_seen_at timestamptz NOT NULL,CHECK(lower_bin_id<=upper_bin_id));
CREATE TABLE IF NOT EXISTS protocol.position_snapshots(id bigserial PRIMARY KEY,position_address text NOT NULL REFERENCES protocol.positions(address),pool_address text NOT NULL REFERENCES protocol.pools(address),chain_slot bigint,total_x numeric(78,0) NOT NULL DEFAULT 0,total_y numeric(78,0) NOT NULL DEFAULT 0,fee_x numeric(78,0),fee_y numeric(78,0),observed_at timestamptz NOT NULL,source text NOT NULL,raw jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS protocol.swap_events(signature text NOT NULL,event_index integer NOT NULL,pool_address text NOT NULL REFERENCES protocol.pools(address),chain_slot bigint,block_time timestamptz,observed_at timestamptz NOT NULL,start_bin_id integer,end_bin_id integer,swap_for_y boolean,amount_in numeric(78,0),amount_out numeric(78,0),mm_fee numeric(78,0),protocol_fee numeric(78,0),limit_order_fee numeric(78,0),host_fee numeric(78,0),payload jsonb NOT NULL,PRIMARY KEY(signature,event_index));
CREATE INDEX IF NOT EXISTS swap_events_pool_slot_idx ON protocol.swap_events(pool_address,chain_slot DESC);
CREATE TABLE IF NOT EXISTS governance.ingestion_checkpoints(stream text PRIMARY KEY,last_seen_slot bigint,last_fully_processed_slot bigint,updated_at timestamptz NOT NULL DEFAULT now(),state jsonb NOT NULL DEFAULT '{}'::jsonb,CHECK(last_fully_processed_slot IS NULL OR last_seen_slot IS NULL OR last_fully_processed_slot<=last_seen_slot));
COMMIT;
